37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
41	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
42	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
43	import org.springframework.samples.petclinic.rest.advice.OwnerDailyRegistrationLimitException;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
