52	import org.springframework.samples.petclinic.util.AddressNormalizer;
53	import org.springframework.samples.petclinic.util.BusinessDayAdjuster;
54	import org.springframework.samples.petclinic.util.EmailNormalizer;
55	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
56	import org.springframework.samples.petclinic.util.OwnerIdentity;
57	import org.springframework.samples.petclinic.util.PostcodeValidator;
58	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
59	import org.springframework.security.access.prepost.PreAuthorize;
60	import org.springframework.web.bind.annotation.CrossOrigin;
61	import org.springframework.web.bind.annotation.RequestMapping;
62	import org.springframework.web.bind.annotation.RestController;
63	import org.springframework.web.context.request.RequestContextHolder;
64	import org.springframework.web.context.request.ServletRequestAttributes;
65	import org.springframework.web.util.UriComponentsBuilder;
66	
67	import jakarta.transaction.Transactional;
68	
69	/**
70	 * @author Vitaliy Fedoriv
71	 */
72	
73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /**
79	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
80	     * carrying the new owner's id, customer code and registration date.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Maximum number of owners a single city may hold. A create whose city already contains this many
86	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
87	     */
88	    private static final int MAX_OWNERS_PER_CITY = 50;
89	
90	    /**
91	     * Maximum number of owners that may be registered in a single day. A create made once this many
92	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
93	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
94	     */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    /**
98	     * The number of owners that must already carry a given day's {@code registrationDate} before a
99	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
100	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
101	     */
102	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
103	
104	    /**
105	     * Request header carrying the client-supplied idempotency key for a create. When a create repeats
106	     * with a key already seen, the originally created owner is returned with {@code 200 OK} instead of
107	     * creating a duplicate (see {@link #addOwner}).
108	     */
109	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
110	
111	    /**
112	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that create originally produced,
113	     * so a repeated create carrying the same key replays that owner rather than creating a duplicate.
114	     */
115	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
116	
117	    private final ClinicService clinicService;
118	
119	    private final OwnerMapper ownerMapper;
120	
121	    private final PetMapper petMapper;
122	
123	    private final VisitMapper visitMapper;
124	
125	    public OwnerRestControllerV1(ClinicService clinicService,
126	                                 OwnerMapper ownerMapper,
127	                                 PetMapper petMapper,
128	                                 VisitMapper visitMapper) {
129	        this.clinicService = clinicService;
130	        this.ownerMapper = ownerMapper;
131	        this.petMapper = petMapper;
132	        this.visitMapper = visitMapper;
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
138	        Collection<Owner> owners;
139	        if (lastName != null) {
140	            owners = this.clinicService.findOwnerByLastName(lastName);
141	        } else {
142	            owners = this.clinicService.findAllOwners();
143	        }
144	        if (owners.isEmpty()) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
153	        Owner owner = this.clinicService.findOwnerById(ownerId);
154	        if (owner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
163	        String idempotencyKey = idempotencyKey();
164	        if (idempotencyKey != null) {
165	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
166	            if (existingId != null) {
167	                Owner existing = this.clinicService.findOwnerById(existingId);
168	                if (existing != null) {
169	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
170	                }
171	            }
172	        }
173	        normalizeAddress(ownerFieldsDto);
174	        rejectBlankOwnerFields(ownerFieldsDto);
175	        rejectInvalidPostcode(ownerFieldsDto);
176	        normalizeTelephone(ownerFieldsDto);
177	        normalizeEmail(ownerFieldsDto);
178	        String householdId = householdIdFor(ownerFieldsDto);
179	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
180	        rejectDuplicateIdentity(ownerFieldsDto, householdId);
181	        rejectHouseholdDuplicate(ownerFieldsDto, householdId, sharesHousehold);
182	        rejectCityAtCapacity(ownerFieldsDto.getCity());
183	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
184	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
185	        long registeredThatDay = countRegisteredOn(registrationDate);
186	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        owner.setRegistrationDate(registrationDate);
190	        owner.setHouseholdId(householdId);
191	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
192	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
193	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
194	        owner.setMembershipLevel(cappedMembershipLevel(owner));
195	        markPossibleDuplicate(owner, sharesHousehold);
196	        this.clinicService.saveOwner(owner);
197	        if (idempotencyKey != null) {
198	            this.idempotentCreates.put(idempotencyKey, owner.getId());
199	        }
200	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
201	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
202	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
203	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
204	        headers.setLocation(UriComponentsBuilder.newInstance()
205	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
206	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
212	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
213	        if (currentOwner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        normalizeAddress(ownerFieldsDto);
217	        currentOwner.setAddress(addressFor(ownerFieldsDto));
218	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
219	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
220	        currentOwner.setCity(ownerFieldsDto.getCity());
221	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
222	        currentOwner.setLastName(ownerFieldsDto.getLastName());
223	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
224	        normalizeEmail(ownerFieldsDto);
225	        currentOwner.setEmail(ownerFieldsDto.getEmail());
226	        currentOwner.setHouseholdId(householdIdFor(ownerFieldsDto));
227	        this.clinicService.saveOwner(currentOwner);
228	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Transactional
233	    @Override
234	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
235	        Owner owner = this.clinicService.findOwnerById(ownerId);
236	        if (owner == null) {
237	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	        }
239	        this.clinicService.deleteOwner(owner);
240	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
241	    }
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner == null) {
248	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	        }
250	        HttpHeaders headers = new HttpHeaders();
251	        Pet pet = petMapper.toPet(petFieldsDto);
252	        owner.setId(ownerId);
253	        pet.setOwner(owner);
254	        pet.getType().setName(null);
255	        this.clinicService.savePet(pet);
256	        PetDto petDto = petMapper.toPetDto(pet);
257	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
258	            .buildAndExpand(pet.getId()).toUri());
259	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
260	    }
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Override
264	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
265	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
266	        if (currentOwner != null) {
267	            Pet currentPet = this.clinicService.findPetById(petId);
268	            if (currentPet != null) {
269	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
270	                currentPet.setName(petFieldsDto.getName());
271	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
272	                this.clinicService.savePet(currentPet);
273	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
274	            }
275	        }
276	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	    }
278	
279	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
280	    @Override
281	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
282	        HttpHeaders headers = new HttpHeaders();
283	        Visit visit = visitMapper.toVisit(visitFieldsDto);
284	        Pet pet = new Pet();
285	        pet.setId(petId);
286	        visit.setPet(pet);
287	        this.clinicService.saveVisit(visit);
288	        VisitDto visitDto = visitMapper.toVisitDto(visit);
289	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
290	            .buildAndExpand(visit.getId()).toUri());
291	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
292	    }
293	
294	
295	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
296	    @Override
297	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
298	        Owner owner = this.clinicService.findOwnerById(ownerId);
299	        if (owner != null) {
300	            Pet pet = owner.getPet(petId);
301	            if (pet != null) {
302	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
303	            }
304	        }
305	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
306	    }
307	
308	    /**
309	     * Reads the optional {@code Idempotency-Key} header from the current request. The generated
310	     * {@code addOwner} signature carries only the request body, so the header is pulled from the
311	     * request bound to the current thread. Returns the trimmed key, or {@code null} when the header is
312	     * absent or blank (in which case the create proceeds normally, without idempotent replay).
313	     *
314	     * @return the non-blank idempotency key, or {@code null} when none was supplied
315	     */
316	    private String idempotencyKey() {
317	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
318	            return null;
319	        }
320	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
321	        return isBlank(key) ? null : key.trim();
322	    }
323	
324	    /**
325	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
326	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
327	     * the request body already rejects null and empty values, but permits whitespace-only strings
328	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
329	     * that gap so every required field must carry a non-blank value.
330	     *
331	     * @param ownerFieldsDto the submitted owner fields
332	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
333	     */
334	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
335	        List<String> missing = new ArrayList<>();
336	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
337	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
338	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
339	            missing.add("address");
340	        }
341	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
342	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
343	        if (!missing.isEmpty()) {
344	            throw new InvalidOwnerFieldsException(missing);
345	        }
346	    }
347	
348	    /**
349	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
350	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
351	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
352	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
353	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
354	     * {@link PostcodeValidator}.
355	     *
356	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
357	     *                       {@link #rejectBlankOwnerFields} having already run)
358	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
359	     */
360	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
361	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
362	            throw new InvalidOwnerFieldsException(List.of("postcode"));
363	        }
364	    }
365	
366	    private void addIfBlank(List<String> missing, String fieldName, String value) {
367	        if (isBlank(value)) {
368	            missing.add(fieldName);
369	        }
370	    }
371	
372	    private boolean isBlank(String value) {
373	        return value == null || value.isBlank();
374	    }
375	
376	    /**
377	     * Normalizes the submitted address on create to its canonical form (see
378	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
379	     * stored and returned, and the form every later address comparison (the required-field check,
380	     * household duplicate detection and the shared household id) is judged on. The structured fields
381	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
382	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
383	     * derived from them when a structured {@code addressLine1} is present, falling back to the
384	     * normalized flat {@code address} otherwise. Any absent field is left absent so
385	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
386	     * after normalization likewise reduces to the empty string and is rejected there.
387	     *
388	     * @param ownerFieldsDto the submitted owner fields
389	     */
390	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
391	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
392	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
393	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
394	        ownerFieldsDto.setAddressLine1(addressLine1);
395	        ownerFieldsDto.setAddressLine2(addressLine2);
396	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
397	    }
398	
399	    /**
400	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
401	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
402	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
403	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
404	     * is the single value every later reader of the address (the required-field check, household
405	     * duplicate detection and the shared household id) is judged on.
406	     *
407	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
408	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
409	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
410	     * @return the composed flat address, or {@code null} when no address form was supplied
411	     */
412	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
413	        if (isBlank(addressLine1)) {
414	            return flatAddress;
415	        }
416	        if (isBlank(addressLine2)) {
417	            return addressLine1;
418	        }
419	        return addressLine1 + " " + addressLine2;
420	    }
421	
422	    /**
423	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
424	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
425	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
426	     * {@code 400 Bad Request}.
427	     *
428	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
429	     *                       {@link #rejectBlankOwnerFields} having already run)
430	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
431	     */
432	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
433	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
434	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
435	        ownerFieldsDto.setTelephone(normalized);
436	    }
437	
438	    /**
439	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
440	     * untouched (email is optional). When present it is reduced to its canonical form (see
441	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
442	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
443	     *
444	     * @param ownerFieldsDto the submitted owner fields
445	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
446	     *                                     or its domain is on the disposable-domain blocklist
447	     */
448	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
449	        String email = ownerFieldsDto.getEmail();
450	        if (email == null || email.isBlank()) {
451	            return;
452	        }
453	        String normalized = EmailNormalizer.normalize(email)
454	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
455	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
456	            throw new InvalidOwnerFieldsException(List.of("email"));
457	        }
458	        ownerFieldsDto.setEmail(normalized);
459	    }
460	
461	    /**
462	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
463	     * duplicate detection is now expressed through the single derived {@code identityKey}
464	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
465	     * which replaces the previously separate telephone, email and household checks. Two owners denote
466	     * the same person when their identities collide on the telephone - the identity's distinguishing
467	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
468	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
469	     * same household with different telephones have different identities and are both allowed; an email
470	     * or a household on its own no longer makes a duplicate.
471	     *
472	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
473	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
474	     * @param householdId    the household id derived for the owner being created (see
475	     *                       {@link HouseholdNormalizer#toHouseholdId})
476	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
477	     */
478	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
479	        String identityKey = OwnerIdentity.identityKey(
480	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
481	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
482	        boolean inUse = activeOwners().stream()
483	            .map(Owner::getTelephone)
484	            .filter(Objects::nonNull)
485	            .map(TelephoneNormalizer::toComparisonKey)
486	            .anyMatch(telephoneKey::equals);
487	        if (inUse) {
488	            throw new DuplicateOwnerIdentityException(identityKey);
489	        }
490	    }
491	
492	    /**
493	     * The owners considered by duplicate detection: every persisted owner except those flagged
494	     * {@code deleted}. A soft-deleted owner is retained but must never make a later create look like a
495	     * duplicate, so both the hard-duplicate identity check ({@link #rejectDuplicateIdentity}) and the
496	     * soft {@linkplain #findPossibleDuplicate possible-duplicate} match are judged against these owners
497	     * alone. Only owners already persisted (before this create) are included.
498	     *
499	     * @return the non-deleted owners currently persisted
500	     */
501	    private List<Owner> activeOwners() {
502	        return this.clinicService.findAllOwners().stream()
503	            .filter(owner -> !owner.isDeleted())
504	            .toList();
505	    }
506	
507	    /**
508	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
509	     * both match the submitted values, compared case-insensitively. The count reflects only owners
510	     * already persisted at the time of the create, so the owner being created is never included.
511	     *
512	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
513	     *                  having already run)
514	     * @param lastName  the submitted last name (non-blank here)
515	     * @return the number of existing owners sharing the same first and last name
516	     */
517	    private int countNamesakes(String firstName, String lastName) {
518	        return (int) this.clinicService.findAllOwners().stream()
519	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
520	                && lastName.equalsIgnoreCase(owner.getLastName()))
521	            .count();
522	    }
523	
524	    /**
525	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
526	     * whose stored {@code householdId} equals the value derived for the owner being created. The
527	     * count reflects only owners already persisted at the time of the create, so the owner being
528	     * created is never included; callers add one to obtain the household size after this create.
529	     *
530	     * @param householdId the household identifier derived for the owner being created (see
531	     *                    {@link HouseholdNormalizer#toHouseholdId})
532	     * @return the number of existing owners already sharing that household
533	     */
534	    private int countHouseholdMembers(String householdId) {
535	        return householdMembers(householdId).size();
536	    }
537	
538	    /**
539	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
540	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
541	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
542	     * created is never among them.
543	     *
544	     * @param householdId the household identifier derived for the owner being created (see
545	     *                    {@link HouseholdNormalizer#toHouseholdId})
546	     * @return the existing owners already sharing that household (empty when {@code householdId} is
547	     *         {@code null})
548	     */
549	    private List<Owner> householdMembers(String householdId) {
550	        if (householdId == null) {
551	            return List.of();
552	        }
553	        return this.clinicService.findAllOwners().stream()
554	            .filter(member -> householdId.equals(member.getHouseholdId()))
555	            .toList();
556	    }
557	
558	    /**
559	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
560	     * {@code membershipLevel} among their existing household members. The owner's own level is the
561	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
562	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
563	     * owner's own level is returned unchanged.
564	     *
565	     * @param owner the owner being created, already stamped with its household id and size
566	     * @return the (possibly capped) membership level to stamp on the owner
567	     */
568	    private int cappedMembershipLevel(Owner owner) {
569	        int ownLevel = this.ownerMapper.membershipLevel(owner);
570	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
571	            .mapToInt(this.ownerMapper::membershipLevel)
572	            .max();
573	        return maxHouseholdLevel.isPresent()
574	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
575	            : ownLevel;
576	    }
577	
578	    /**
579	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
580	     * owner with an address taken from the request, so routing that through this single method keeps the
581	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
582	     * household id.
583	     *
584	     * @param ownerFieldsDto the submitted owner fields
585	     * @return the address to store on the owner
586	     */
587	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
588	        return ownerFieldsDto.getAddress();
589	    }
590	
591	    /**
592	     * Derives the household id an owner should carry from its submitted fields (see
593	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
594	     * household id, so routing them through this single method keeps them agreed on which of the
595	     * owner's fields key the household.
596	     *
597	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
598	     *                       {@link #rejectBlankOwnerFields} having already run on create)
599	     * @return the owner's household id
600	     */
601	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
602	        return HouseholdNormalizer.toHouseholdId(
603	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
604	    }
605	
606	    /**
607	     * Rejects creating an owner that would join an existing household as an indistinguishable
608	     * near-duplicate without declaring itself a member. The household is keyed on (last name,
609	     * postcode) through the derived {@code householdId} (see {@link HouseholdNormalizer#toHouseholdId}),
610	     * so a second owner sharing an existing owner's last name and postcode denotes the same household.
611	     * A genuinely distinct household member is told apart by its telephone: an owner whose normalized
612	     * telephone differs from every existing member's is a legitimate additional member (recorded as a
613	     * {@linkplain #findPossibleDuplicate possible duplicate}, not rejected). Only a create that shares
614	     * both the household and an existing member's telephone is reported as a {@code 409 Conflict},
615	     * unless it opts in with {@code sharesHousehold}, in which case it is accepted as a declared
616	     * household member. Only owners already persisted (before this create) are considered.
617	     *
618	     * @param ownerFieldsDto  the submitted owner fields (telephone already normalized)
619	     * @param householdId     the household id derived for the owner being created
620	     * @param sharesHousehold whether the request opted in to sharing a household
621	     * @throws DuplicateOwnerHouseholdException if an existing member shares the household and telephone
622	     *                                          and the request did not opt in with {@code sharesHousehold}
623	     */
624	    private void rejectHouseholdDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId,
625	            boolean sharesHousehold) {
626	        if (sharesHousehold || householdId == null) {
627	            return;
628	        }
629	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
630	        boolean indistinguishableMember = activeOwners().stream()
631	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
632	            .filter(existing -> existing.getTelephone() != null)
633	            .anyMatch(existing -> telephoneKey.equals(
634	                TelephoneNormalizer.toComparisonKey(existing.getTelephone())));
635	        if (indistinguishableMember) {
636	            throw new DuplicateOwnerHouseholdException(householdId);
637	        }
638	    }
639	
640	    /**
641	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
642	     * is none. The create has already cleared the hard-duplicate identity check
643	     * ({@link #rejectDuplicateIdentity}), so it is not an exact match of any existing owner; it is a
644	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code lastName}
645	     * (compared case-insensitively) and {@code postcode} while carrying a different normalized
646	     * telephone. The oldest such owner (the earliest persisted) is returned so the flag points at the
647	     * original record; owners with no postcode never match, since a shared postcode is required.
648	     *
649	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
650	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
651	     *         duplicate
652	     */
653	    private Integer findPossibleDuplicate(Owner owner) {
654	        String postcode = owner.getPostcode();
655	        if (postcode == null) {
656	            return null;
657	        }
658	        String telephoneKey = TelephoneNormalizer.toComparisonKey(owner.getTelephone());
659	        return activeOwners().stream()
660	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
661	            .filter(existing -> postcode.equals(existing.getPostcode()))
662	            .filter(existing -> existing.getTelephone() != null
663	                && !telephoneKey.equals(TelephoneNormalizer.toComparisonKey(existing.getTelephone())))
664	            .map(Owner::getId)
665	            .filter(Objects::nonNull)
666	            .min(Integer::compareTo)
667	            .orElse(null);
668	    }
669	
670	    /**
671	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
672	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
673	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
674	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
675	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
676	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
677	     * duplicate, so it is never flagged.
678	     *
679	     * @param owner           the owner being created, with telephone already normalized and
680	     *                        lastName/postcode set
681	     * @param sharesHousehold whether the request opted in to sharing a household
682	     */
683	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
684	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
685	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
686	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
687	    }
688	
689	    /**
690	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
691	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
692	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
693	     *
694	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
695	     *             run)
696	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
697	     */
698	    private void rejectCityAtCapacity(String city) {
699	        long ownersInCity = this.clinicService.findAllOwners().stream()
700	            .map(Owner::getCity)
701	            .filter(Objects::nonNull)
702	            .filter(city::equalsIgnoreCase)
703	            .count();
704	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
705	            throw new OwnerCityAtCapacityException(city);
706	        }
707	    }
708	
709	    /**
710	     * Resolves the effective registration date for a create, rolled onto a business day. The
711	     * supplied date is used when present, otherwise the server's current date; either way the result
712	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
713	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
714	     * stored {@code registrationDate}, the membership number's year segment and the daily
715	     * create-limit's per-day count - is judged on this adjusted date.
716	     *
717	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
718	     *                                 default to the server's current date
719	     * @return the effective registration date, guaranteed to fall on a business day
720	     */
721	    /**
722	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
723	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
724	     * adjustment; a future date cannot describe a registration that has already happened, so it is
725	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
726	     * server's current date) and any date on or before today are accepted.
727	     *
728	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
729	     *                                 omitted
730	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
731	     */
732	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
733	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
734	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
735	        }
736	    }
737	
738	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
739	        LocalDate registrationDate =
740	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
741	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
742	    }
743	
744	    /**
745	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
746	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
747	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
748	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
749	     * Too Many Requests}.
750	     *
751	     * @param registrationDate   the create's effective registration date, already rolled onto a
752	     *                           business day by {@link #effectiveRegistrationDate}
753	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
754	     *                           {@code registrationDate} equals {@code registrationDate}
755	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
756	     *                                              owner registrations
757	     */
758	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
759	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
760	            throw new OwnerDailyRegistrationLimitException(registrationDate);
761	        }
762	    }
763	
764	    /**
765	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
766	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
767	     * bulk-signup warning are judged on.
768	     *
769	     * @param registrationDate the create's effective registration date, already rolled onto a business
770	     *                         day by {@link #effectiveRegistrationDate}
771	     * @return the number of existing owners registered on that day
772	     */
773	    private long countRegisteredOn(LocalDate registrationDate) {
774	        return this.clinicService.findAllOwners().stream()
775	            .map(Owner::getRegistrationDate)
776	            .filter(registrationDate::equals)
777	            .count();
778	    }
779	}
